def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    supply = day_context['supply']
    hp = my_status['hp']
    budget = my_status['budget']
    no_water_days = my_status['no_water_days']

    if budget <= 0:
        return 0

    alive = []
    prev_bids = []
    urgent_opp = 0
    rich_opp = 0
    for opp in opponents_status.values():
        if opp.get('alive'):
            alive.append(opp)
            if opp.get('budget', 0) > budget:
                rich_opp += 1
            if opp.get('no_water_days', 0) >= 1 or opp.get('hp', 10) <= 3:
                urgent_opp += 1
            prev = opp.get('previous_trace', {})
            if prev and prev.get('bid') is not None:
                prev_bids.append(prev.get('bid', 0))

    if not alive:
        return min(budget, 18)

    competition = len(alive) + 1
    scarcity = float(supply) / float(competition * WATER_REQ)

    if prev_bids:
        highest_prev = max(prev_bids)
        avg_prev = sum(prev_bids) / len(prev_bids)
    else:
        highest_prev = 0
        avg_prev = 0

    if hp <= 2 or no_water_days >= 2:
        target = max(63, highest_prev + 3)
    elif hp <= 4 or no_water_days >= 1:
        if scarcity < 0.5:
            target = max(56, highest_prev + 2)
        else:
            target = max(44, avg_prev + 2)
    else:
        if scarcity >= 1.0:
            target = 18
        elif scarcity >= 0.75:
            target = max(24, avg_prev + 1)
        elif scarcity >= 0.5:
            target = max(34, highest_prev + 1.5)
        else:
            target = max(48, highest_prev + 2.5)

    if urgent_opp >= max(1, len(alive) // 2):
        target += 4
    if rich_opp >= max(1, len(alive) // 2):
        target += 3

    if budget < 20:
        target = min(target, budget)
    elif budget < 50:
        target = min(target, 0.8 * budget)
    else:
        target = min(target, 0.6 * budget + 12)

    target = max(0, min(budget, target))
    return float(target)

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 9
    DAILY_SALARY = 90

    supply = day_context['supply']
    day = day_context['day']

    budget = my_status['budget']
    hp = my_status['hp']

    alive_opponents = []
    for opp in opponents_status.values():
        if opp.get('alive', False):
            alive_opponents.append(opp)

    # If no opponents, take a safe moderate bid.
    if not alive_opponents:
        if hp <= 2:
            return min(budget, DAILY_SALARY * 0.85)
        return min(budget, DAILY_SALARY * 0.55)

    # Read yesterday's behavior from previous_trace.
    yesterday_bids = []
    for opp in alive_opponents:
        prev = opp.get('previous_trace', {})
        bid = prev.get('bid', None)
        if bid is not None:
            yesterday_bids.append(bid)

    # Default if no trace.
    if not yesterday_bids:
        if hp <= 2:
            return min(budget, DAILY_SALARY * 0.8)
        return min(budget, DAILY_SALARY * 0.5)

    highest_prev_bid = max(yesterday_bids)
    lowest_prev_bid = min(yesterday_bids)

    # Estimate how many full water units we can roughly aim for.
    # Ensure indices are int-safe.
    # Target units based on supply: round down to avoid overshooting.
    target_units = int(supply // float(WATER_REQ))
    if target_units < 1:
        target_units = 1

    # Convert target units to a bid pressure level.
    # Higher target_units implies we want more water; map to bid fraction.
    # target_units of 1..2 (since supply range 15..25) => fractions 0.45..0.65
    if target_units <= 1:
        base_frac = 0.45
    else:
        base_frac = 0.65

    # If opponents previously bid very high, they were likely desperate.
    high_threshold = DAILY_SALARY * 0.85
    mid_threshold = DAILY_SALARY * 0.6

    if highest_prev_bid >= high_threshold:
        # Avoid getting into a pure bidding war; still bid enough to secure water.
        if hp <= 2:
            frac = 0.9
        else:
            frac = max(base_frac, 0.6)
    elif highest_prev_bid >= mid_threshold:
        # Moderate competition: slightly outbid to secure advantage.
        frac = max(base_frac, 0.55)
        # Nudge upward if our hp is healthy.
        if hp >= 4:
            frac = min(0.75, frac + 0.1)
    else:
        # They were not bidding aggressively; take more supply share.
        frac = max(base_frac, 0.6)
        if hp <= 2:
            frac = min(frac, 0.75)

    # Additional adjustment: if their lowest bid was also low, increase aggressiveness.
    if lowest_prev_bid < DAILY_SALARY * 0.35:
        if hp >= 4:
            frac = min(0.8, frac + 0.1)

    bid = DAILY_SALARY * frac

    # Never exceed budget.
    if bid > budget:
        bid = budget

    # If hp is critically low, conserve budget.
    if hp <= 1:
        bid = min(bid, DAILY_SALARY * 0.7)

    # Ensure non-negative.
    if bid < 0:
        bid = 0

    return bid

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 8
    DAILY_SALARY = 140
    supply = day_context['supply']
    day = int(day_context['day'])
    hp = my_status['hp']
    budget = my_status['budget']
    no_water_days = my_status['no_water_days']

    alive_opponents = [o for o in opponents_status.values() if o['alive']]
    if not alive_opponents:
        return min(budget, DAILY_SALARY * 0.4)

    # Collect yesterday's bids from opponents
    yesterday_bids = []
    for opp in alive_opponents:
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            yesterday_bids.append(float(prev['bid']))

    # Base bid: start with a moderate amount
    base_bid = DAILY_SALARY * 0.4

    # Adjust based on HP
    if hp <= 2:
        base_bid = DAILY_SALARY * 0.9
    elif hp <= 4:
        base_bid = DAILY_SALARY * 0.65

    # If we are desperate (no water days > 2), bid very high
    if no_water_days >= 2:
        base_bid = DAILY_SALARY * 0.95

    # Try to outbid yesterday's highest if we have budget
    if yesterday_bids:
        highest_prev = max(yesterday_bids)
        # Only escalate if we can reasonably outbid by a small margin
        if highest_prev > base_bid and budget > highest_prev + 2:
            base_bid = min(budget, highest_prev + 2)
        elif highest_prev > base_bid and budget <= highest_prev + 2:
            # If we can't outbid, try a safe bid
            base_bid = min(budget, base_bid)
        else:
            # Already higher, stick with base
            base_bid = max(base_bid, highest_prev + 0.5)

    # Final bound: cannot exceed budget and cannot be negative
    return max(0, min(budget, base_bid))
